#' X = matrix(rnorm(n*p), n, p)
#' colnames(X) = seq(p)
#' X_design = matrix(rnorm(n*nc), n,nc)
#' w = seq(n)
#' w = w / mean(w)
#' 
#' # fit regressions with model j including X[,j]
#' fit = lmFitFeatures(y, X_design, X, colnames(X), w)
#' 
#' # examine results
#' lapply(fit, head, 2)
#' 
#' @export
